    Json(FileIconVectors.Json),
    Markdown(FileIconVectors.Markdown),
    Shell(FileIconVectors.Shell),
    Yaml(FileIconVectors.Yaml),
    Config(FileIconVectors.Config),
    Xml(FileIconVectors.Xml),
    Java(FileIconVectors.Java),
    Kotlin(FileIconVectors.Kotlin),
    Swift(FileIconVectors.Swift),
    Go(FileIconVectors.Go),
    Rust(FileIconVectors.Rust),
    Ruby(FileIconVectors.Ruby),
    Php(FileIconVectors.Php),
    Lua(FileIconVectors.Lua),
    Sql(FileIconVectors.Db),
    Bat(FileIconVectors.Windows),

    // Assets
    Image(FileIconVectors.Image),
    Svg(FileIconVectors.Svg),
    Zip(FileIconVectors.Zip),
    Audio(FileIconVectors.Audio),
    Video(FileIconVectors.Video),
    Font(FileIconVectors.Font),

    // Defaults
    Folder(SpckIcons.FolderLine, tintable = false), // use SpckIcons.FolderLine? Or Seti Folder?
    Default(FileIconVectors.Default);

    companion object {
        fun resolve(name: String, isDirectory: Boolean = false): FileIcon {
            if (isDirectory) {
                if (name == ".git") return GitFolder
                if (name == ".github") return GithubFolder
                return Folder
            }
            
            val lower = name.lowercase()
            return when (lower) {
                "dockerfile" -> Dockerfile
                ".gitignore" -> GitIgnore
                "package.json" -> PackageJson
                "makefile" -> Makefile
                "cmakelists.txt" -> CMakeLists
                else -> {
                    val extIndex = lower.lastIndexOf('.')
                    if (extIndex <= 0) { // no extension (0 means dotfile like .env)
                        if (extIndex == 0) return Config // dotfile
                        return Default
                    }
                    val ext = lower.substring(extIndex + 1)
                    when (ext) {
                        "c", "h" -> C
                        "cpp", "hpp", "cc", "cxx", "hxx", "hh" -> Cpp
                        "py", "pyw" -> Python
                        "js", "mjs", "cjs" -> Javascript
                        "ts" -> Typescript
                        "tsx", "jsx" -> React
                        "html", "htm" -> Html
                        "css" -> Css
                        "scss" -> Sass
                        "json" -> Json
                        "md", "markdown" -> Markdown
                        "sh", "bash", "zsh" -> Shell
                        "yaml", "yml" -> Yaml
                        "toml" -> Config
                        "xml" -> Xml
                        "java" -> Java
                        "kt" -> Kotlin
                        "swift" -> Swift
                        "go" -> Go
                        "rs" -> Rust
                        "rb" -> Ruby
                        "php" -> Php
                        "lua" -> Lua
                        "sql" -> Sql
                        "bat" -> Bat
                        
                        "png", "jpg", "jpeg", "gif", "webp" -> Image
                        "svg" -> Svg
                        "zip", "tar", "gz" -> Zip
                        "mp3", "wav" -> Audio
                        "mp4", "webm" -> Video
                        "ttf", "woff", "woff2" -> Font
                        
                        else -> Default
                    }
                }
            }
        }
    }
}
